html:
{%- set brand = frappe.get_doc("GRC Maturity Brand", doc.brand) if doc.brand else None -%}
{%- set theme = frappe.get_doc("GRC Maturity Theme", brand.theme) if brand else None -%}
{%- set settings = frappe.get_doc("GRC Maturity Settings") -%}
{%- set ar = (doc.language == "ar") -%}
{%- set primary = (theme.primary_color if theme and theme.primary_color else "#1e3a5f") -%}
{%- set sections = doc.results | selectattr("result_level", "equalto", "Section") | list -%}
{%- set topics = doc.results | selectattr("result_level", "equalto", "Topic") | list -%}
<div dir="{{ 'rtl' if ar else 'ltr' }}" style="font-family: {{ 'Tahoma, Arial' if ar else 'Segoe UI, Roboto, Arial' }}, sans-serif; color:#1e2a3a; font-size:11px;">
<style>
	.axr h2 { font-size: 15px; color: {{ primary }}; border-bottom: 2px solid #e7edf4; padding-bottom: 4px; margin: 18px 0 8px; }
	.axr table { width: 100%; border-collapse: collapse; }
	.axr th { background: #eef3fa; padding: 5px 6px; text-align: {{ 'right' if ar else 'left' }}; font-weight: 600; }
	.axr td { padding: 4px 6px; border-bottom: 1px solid #eef3fa; vertical-align: top; }
	.axr .bar { height: 6px; background: #e7edf4; border-radius: 6px; overflow: hidden; }
	.axr .bar div { height: 6px; border-radius: 6px; }
	.axr .muted { color: #5a6f87; }
	.axr .card { border: 1px solid #e7edf4; border-radius: 8px; padding: 6px 8px; }
</style>
<div class="axr">
	<table style="margin-bottom:10px"><tr>
		<td style="border:0;width:60%">
			{% if brand and brand.logo %}<img src="{{ frappe.utils.get_url(brand.logo) }}" style="max-height:44px;max-width:180px"><br>{% endif %}
			<div style="font-size:18px;font-weight:700;color:{{ primary }}">{{ (brand.app_title_ar if ar and brand and brand.app_title_ar else (brand.app_title if brand else _("GRC Maturity Assessment"))) }}</div>
			<div class="muted">{{ _("Assessment Report") }} · {{ doc.name }} · {{ frappe.utils.format_datetime(doc.submitted_on or doc.modified, "dd-MM-yyyy HH:mm") }}</div>
		</td>
		<td style="border:0;text-align:{{ 'left' if ar else 'right' }}">
			<div style="font-size:32px;font-weight:700;line-height:1">{{ "%.1f" | format(doc.overall_percentage or 0) }}%</div>
			<div style="display:inline-block;margin-top:4px;padding:2px 12px;border-radius:20px;background:{{ doc.band_color or primary }};color:#fff;font-weight:600">{{ doc.maturity_band or "" }}</div>
			<div class="muted" style="margin-top:3px">{{ _("Points") }}: {{ "%.2f" | format(doc.points_earned or 0) }} / {{ "%.2f" | format(doc.points_possible or 0) }} · {{ doc.answered_count }}/{{ doc.question_count }} {{ _("answered") }}{% if doc.na_count %} · {{ doc.na_count }} {{ _("N/A") }}{% endif %}</div>
		</td></tr></table>

	<div class="card"><b>{{ doc.organization_name }}</b> · {{ doc.industry_type }} · {{ doc.sector_other or frappe.db.get_value("GRC Maturity Industry Sector", doc.industry_sector, "sector_name") }} · {{ doc.company_nationality }}
		{% if doc.cr_number %} · CR {{ doc.cr_number }}{% endif %}{% if doc.legal_form %} · {{ doc.legal_form }}{% endif %}{% if doc.entity_size %} · {{ doc.entity_size }}{% endif %}
		<br><span class="muted">{% if doc.license_na %}{{ _("No KSA license") }}{% else %}{{ _("Licenses") }}: {{ doc.license_types_text or (doc.licenses | map(attribute="license_name") | join(", ")) }}{% endif %}</span>
		<br><span class="muted">{% for r in doc.regulators %}{{ r.regulator }}: {{ _(r.response) if r.response else "—" }}{% if not loop.last %} | {% endif %}{% endfor %}{% if doc.other_regulator %} | {{ doc.other_regulator }}{% endif %}</span>
	</div>

	{% if not doc.license_na and doc.licenses %}
	<h2>{{ _("KSA licenses") }}</h2>
	<table><tr><th>{{ _("License") }}</th><th>{{ _("Still valid") }}</th><th>{{ _("Expiry date") }}</th></tr>
	{% for l in doc.licenses %}<tr><td>{{ l.license_name or l.license_type }}</td><td>{{ _(l.is_valid) if l.is_valid else "" }}</td><td>{{ frappe.utils.formatdate(l.expiry_date) if l.expiry_date else "" }}</td></tr>{% endfor %}</table>
	{% endif %}

	<h2>{{ _("Sections") }}</h2>
	<table><tr><th>{{ _("Section") }}</th><th style="width:40%"></th><th>{{ _("Score") }}</th><th>{{ _("Level") }}</th><th>{{ _("Answered") }}</th></tr>
	{% for r in sections %}<tr><td>{{ r.label }}</td><td><div class="bar"><div style="width:{{ r.percentage or 0 }}%;background:{{ r.band_color or primary }}"></div></div></td><td>{{ "%.1f" | format(r.percentage or 0) }}%</td><td>{{ r.band }}</td><td>{{ r.answered }}/{{ r.total }}</td></tr>{% endfor %}</table>

	{% if topics %}<h2>{{ _("Topics") }}</h2>
	<table><tr><th>{{ _("Topic") }}</th><th style="width:40%"></th><th>{{ _("Score") }}</th><th>{{ _("Level") }}</th></tr>
	{% for r in topics %}<tr><td>{{ r.label }}</td><td><div class="bar"><div style="width:{{ r.percentage or 0 }}%;background:{{ r.band_color or primary }}"></div></div></td><td>{{ "%.1f" | format(r.percentage or 0) }}%</td><td>{{ r.band }}</td></tr>{% endfor %}</table>{% endif %}

	{%- set roadmap = doc.answers | selectattr("target_description") | list -%}
	{% if roadmap %}<h2>{{ _("Improvement roadmap") }}</h2>
	<table><tr><th style="width:7%"></th><th style="width:38%">{{ _("Question") }}</th><th style="width:20%">{{ _("Current") }}</th><th>{{ _("Next target") }}</th></tr>
	{% for a in roadmap %}<tr><td><b>{{ a.question_code }}</b></td><td>{{ a.question_text }}</td><td>{{ a.selected_label }}</td><td>{{ a.target_description }}</td></tr>{% endfor %}</table>{% endif %}

	<h2>{{ _("Answers") }}</h2>
	<table><tr><th style="width:7%">{{ _("Question") }}</th><th></th><th style="width:16%">{{ _("Selected") }}</th><th style="width:9%">{{ _("Score") }}</th></tr>
	{% for a in doc.answers %}<tr><td><b>{{ a.question_code }}</b></td><td>{{ a.question_text }}</td><td>{{ a.selected_value or "—" }}{% if a.selected_label and a.selected_value != "NA" %} · {{ a.selected_label }}{% endif %}{% if a.selected_value == "NA" %} {{ _("N/A") }}{% endif %}</td><td>{% if a.is_na %}—{% else %}{{ a.points | int }}/{{ a.max_points | int }}{% endif %}</td></tr>{% endfor %}</table>

	{% if doc.consultant_notes and doc.status in ("Reviewed", "Closed") %}<h2>{{ _("Consultant notes") }}</h2><div>{{ doc.consultant_notes }}</div>{% endif %}

	<h2>{{ _("Maturity Interpretation") }}</h2>
	<ul>{% for b in settings.bands | sort(attribute="min_pct") %}<li><b>{{ b.band_label_ar if ar and b.band_label_ar else b.band_label }} ({{ b.min_pct | int }}–{{ b.max_pct | round | int }}%)</b>: {{ b.interpretation_ar if ar and b.interpretation_ar else b.interpretation }}</li>{% endfor %}</ul>
	<p class="muted">{{ _("Questions answered N/A are left out of the score.") }} {{ _("Roll-up") }}: {{ _(doc.rollup_method) }}.</p>
	{% if brand %}<p class="muted">{{ brand.report_disclaimer_ar if ar and brand.report_disclaimer_ar else (brand.report_disclaimer or "") }}</p>
	<p class="muted" style="margin-top:14px;border-top:1px solid #e7edf4;padding-top:6px">{{ brand.footer_text_ar if ar and brand.footer_text_ar else (brand.footer_text or "") }}{% if not brand.white_label and brand.powered_by_text %} · {{ brand.powered_by_text }}{% endif %}</p>{% endif %}
</div></div>
